/*
 * A354964  a(1) = 1, a(2) = 2, a(3) = 3; for n > 3, a(n) is the smallest new
 *          number such that the sum of any four successive terms is prime.
 * https://oeis.org/A354964
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by a greedy search
 * Range:     u8 n <= 52, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   isPrimeGeneric
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(1)=1, a(2)=2, a(3)=3; for n>3 the smallest unused integer is chosen
   so that the sum of the last four consecutive terms is prime. */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/isPrimeGeneric.h"

/* Memoised sequence storage */
static seq_t *seq = NULL;          /* array of terms */
static size_t seqCap = 0;          /* allocated capacity */
static size_t seqLen = 0;          /* number of terms currently computed */

/* Tracking of used integers */
static unsigned char *used = NULL; /* bitmask of used numbers */
static idx_t usedCap = 0;          /* maximum value tracked (exact index) */

/* Ensure the sequence storage can hold at least 'n' terms. */
static void ensure_seq_capacity(size_t n)
{
    if (n <= seqCap)
        return;
    size_t newCap = seqCap ? seqCap * 2 : 8;
    if (newCap < n)
        newCap = n;
    seq_t *newSeq = (seq_t *)malloc(newCap * sizeof(seq_t));
    if (seq)
        memcpy(newSeq, seq, seqLen * sizeof(seq_t));
    free(seq);
    seq = newSeq;
    seqCap = newCap;
}

/* Ensure the 'used' array can index up to 'v' (inclusive). */
static void ensure_used_capacity(idx_t v)
{
    if ((idx_t)v <= usedCap)
        return;
    size_t newCap = (size_t)(v) + 1;           /* one extra for 0 index */
    unsigned char *newUsed = (unsigned char *)malloc(newCap);
    memset(newUsed, 0, newCap);
    if (used && usedCap > 0)
        memcpy(newUsed, used, usedCap + 1);
    free(used);
    used = newUsed;
    usedCap = v;
}

/* Return the nth element of the sequence. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                           /* undefined, but harmless */

    /* 1‑based index to 0‑based array size */
    size_t required = (size_t)n;
    ensure_seq_capacity(required);

    /* Compute missing terms up to 'required' */
    for (size_t i = seqLen + 1; i <= required; ++i) {
        if (i == 1) {
            seq[0] = (seq_t)1;
            ensure_used_capacity(1);
            used[1] = 1;
        } else if (i == 2) {
            seq[1] = (seq_t)2;
            ensure_used_capacity(2);
            used[2] = 1;
        } else if (i == 3) {
            seq[2] = (seq_t)3;
            ensure_used_capacity(3);
            used[3] = 1;
        } else {
            /* Search for the smallest unused integer that keeps the
               last four‑term sum prime. */
            for (idx_t cand = 1; ; ++cand) {
                ensure_used_capacity(cand);
                if (used[cand])
                    continue;
                seq_t sum = seq[i - 4] + seq[i - 3] + seq[i - 2] + (seq_t)cand;
                if (isPrimeGeneric(sum)) {
                    seq[i - 1] = (seq_t)cand;
                    used[cand] = 1;
                    break;
                }
            }
        }
    }

    seqLen = required;
    return seq[n - 1];
}
